1007	// trailUpdateHasChanges reports whether any field would actually be sent.
1008	func trailUpdateHasChanges(inputs trailUpdateInputs) bool {
1009		return inputs.StatusChanged || inputs.TitleChanged || inputs.BodyChanged ||
1010			len(inputs.LabelAdd) > 0 || len(inputs.LabelRemove) > 0
1011	}
