1168	// applyTrailUpdate writes the requested changes to a resolved trail. Body and
1169	// metadata are sent as SEPARATE PATCHes because the API rejects combining them:
1170	// the body is a collaborative editor document written through a Durable Object,
1171	// metadata is a row update, and the two share no transaction. Metadata is sent
1172	// first; if the body PATCH then fails, the error states the metadata already
1173	// landed so the partial outcome isn't hidden.
1174	func applyTrailUpdate(ctx context.Context, client *api.Client, forge, owner, repo string, found *api.TrailResource, inputs trailUpdateInputs) error {
1175		// The single-trail endpoint is keyed by trail number; ids/branches are
1176		// resolved to a number before this point.
1177		if found.Number <= 0 {
1178			return fmt.Errorf("%s has no number yet; cannot update", describeTrailRef(found))
1179		}
1180		path := trailNumberPath(forge, owner, repo, found.Number)
1181	
1182		metadataChanged := inputs.StatusChanged || inputs.TitleChanged || len(inputs.LabelAdd) > 0 || len(inputs.LabelRemove) > 0
1183		if metadataChanged {
1184			req := buildTrailUpdateRequest(found, trailUpdateInputs{
1185				Status:        inputs.Status,
1186				StatusChanged: inputs.StatusChanged,
1187				Title:         inputs.Title,
1188				TitleChanged:  inputs.TitleChanged,
1189				LabelAdd:      inputs.LabelAdd,
1190				LabelRemove:   inputs.LabelRemove,
1191			})
1192			if err := patchTrail(ctx, client, path, req); err != nil {
1193				return err
1194			}
1195		}
1196		if inputs.BodyChanged {
1197			if err := patchTrail(ctx, client, path, api.TrailUpdateRequest{Body: &inputs.Body}); err != nil {
1198				if metadataChanged {
1199					return fmt.Errorf("metadata updated, but body update failed: %w", err)
1200				}
1201				return err
1202			}
1203		}
1204		return nil
1205	}
1206	
1207	func patchTrail(ctx context.Context, client *api.Client, path string, req api.TrailUpdateRequest) error {
1208		resp, err := client.Patch(ctx, path, req)
1209		if err != nil {
1210			return fmt.Errorf("failed to update trail: %w", err)
1211		}
1212		defer resp.Body.Close()
1213		if err := checkTrailResponse(resp); err != nil {
1214			return err
1215		}
1216		var updateResp api.TrailUpdateResponse
1217		if err := api.DecodeJSON(resp, &updateResp); err != nil {
1218			return fmt.Errorf("failed to decode update response: %w", err)
1219		}
1220		return nil
1221	}
1222	
1223	func validateTrailUpdateFields(inputs trailUpdateInputs) error {
1224		if inputs.TitleChanged && strings.TrimSpace(inputs.Title) == "" {
1225			return errors.New("trail title is required")
1226		}
1227		if inputs.StatusChanged {
1228			status := trail.Status(strings.TrimSpace(inputs.Status))
1229			if !status.IsValid() {
1230				return fmt.Errorf("invalid status %q: valid values are %s", inputs.Status, formatValidStatuses())
1231			}
1232		}
1233		return nil
